class Solution:
    def majorityElement(self, nums: List[int]) -> int:
        cand, count = None, 0
        for x in nums:
            if count == 0:
                cand = x                    # 票数归零，换候选人
            count += 1 if x == cand else -1 # 相同 +1，不同就抵消一票
        return cand

class Solution:
    def majorityElement(self, nums: List[int]) -> int:
        return sorted(nums)[len(nums) // 2]

